/* Read-only browsing of exported historical annotations; no database writes. */
(function(root){
'use strict';const q=s=>document.querySelector(s),C=ECGCore;const H={manifest:null,files:null,prefix:'',selected:null,wave:null,records:null,start:0,token:0};
const safe=p=>typeof p==='string'&&p.length<400&&!p.startsWith('/')&&!p.includes('\\')&&!p.split('/').some(x=>!x||x==='.'||x==='..');
async function jsonFile(file,limit=10*1024*1024){if(!file||file.size>limit)throw Error('Missing or oversized history file.');let bytes;if(file.name.endsWith('.gz')){const reader=new Blob([await file.arrayBuffer()]).stream().pipeThrough(new DecompressionStream('gzip')).getReader(),parts=[];let total=0;try{while(true){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>limit)throw Error('History file expands beyond the size limit.');parts.push(value);}}catch(e){await reader.cancel().catch(()=>{});throw e;}bytes=await new Blob(parts).arrayBuffer();}else bytes=await file.arrayBuffer();return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
function validate(m){if(m?.format!=='ecg-annotation-archive'||m.version!==1||!Array.isArray(m.items)||!m.items.length||m.items.length>5000||typeof m.title!=='string'||m.title.length>200)throw Error('Invalid annotation history manifest.');const ids=new Set();for(const t of m.items){if(!C.id(t.id)||ids.has(t.id)||!['R_peak','Direction','Method_preference'].includes(t.kind)||!['Random','Difficult','Unclassified'].includes(t.samplingGroup)||typeof t.durationGroup!=='string'||t.durationGroup.length>40||!safe(t.recordsFile)||!Array.isArray(t.peaks)||t.peaks.length>200000||!t.peaks.every(i=>Number.isInteger(i)&&i>=0)||!Array.isArray(t.unreadable)||t.unreadable.some(r=>!Array.isArray(r)||r.length!==2||r.some(x=>typeof x!=='number'||!Number.isFinite(x))))throw Error('Invalid annotation history item.');if(t.waveform&&(!safe(t.waveform.file)||!/^[a-f0-9]{64}$/.test(t.waveform.sha256)||!Number.isInteger(t.waveform.sampleCount)||t.waveform.sampleCount<2||t.waveform.sampleCount>200000))throw Error('Invalid historical waveform reference.');ids.add(t.id);}return true;}
function listed(){const duration=q('#history-duration').value,sampling=q('#history-sampling').value,kind=q('#history-kind').value,search=q('#history-search').value.toLowerCase().trim();return H.manifest.items.filter(t=>(!duration||t.durationGroup===duration)&&(!sampling||t.samplingGroup===sampling)&&(!kind||t.kind===kind)&&(!search||`${t.participant} ${t.clipId} ${t.reviewer}`.toLowerCase().includes(search)));}
function list(){const host=q('#history-list');host.replaceChildren();const items=listed();q('#history-count').textContent=`${items.length} / ${H.manifest.items.length} tasks shown`;let current='';for(const t of items){const group=t.durationGroup+' / '+t.samplingGroup;if(group!==current){const h=document.createElement('h3');h.className='duration-heading';h.textContent=group;host.append(h);current=group;}const b=document.createElement('button');b.className='task-button'+(H.selected?.id===t.id?' active':'');const title=document.createElement('strong'),meta=document.createElement('small');title.textContent=t.participant+' · '+t.clipId;meta.textContent=`${t.kind} · ${t.reviewer} · ${t.status}`;b.append(title,meta);b.onclick=()=>select(t).catch(showError);host.append(b);}}
function showError(e){q('#history-wave-message').textContent=e.message||String(e);q('#history-wave-message').className='error';}
async function select(t){const token=++H.token;H.selected=t;H.wave=null;H.records=null;H.start=0;list();q('#history-category').textContent=t.durationGroup+' / '+t.samplingGroup+' / '+t.kind;q('#history-task-title').textContent=t.participant+' · '+t.clipId;q('#history-task-meta').textContent=`Reviewer: ${t.reviewer} · Status: ${t.status} · ${t.recordCount} saved records`;q('#history-classification').textContent=t.classificationBasis==='uncertain_default_random'?'Random is inherited from the earlier organization; the original sampling method was not established.':`Classification basis: ${t.classificationBasis}`;q('#history-details').textContent=JSON.stringify({semantic:t.semantic,...t.summary,waveform:t.waveform,classificationBasis:t.classificationBasis},null,2);q('#history-labels').replaceChildren();for(const [k,v]of Object.entries(t.summary||{})){if(!['direction','choice','confidence','minute_directions_json','qrs_readability','direction_determinability'].includes(k))continue;const span=document.createElement('span');span.textContent=k+': '+v;q('#history-labels').append(span);}q('#history-records').replaceChildren();q('#history-wave-message').className='';q('#history-wave-message').textContent=t.waveform?'Checking historical waveform locally…':t.waveformUnavailableReason;
 const records=await jsonFile(H.files.get(H.prefix+t.recordsFile));if(token!==H.token)return;H.records=records;renderRecords(records.rows);
 if(t.waveform){const file=H.files.get(H.prefix+t.waveform.file);if(!file||await C.sha256(await file.arrayBuffer())!==t.waveform.sha256)throw Error('Historical waveform checksum does not match.');const w=await jsonFile(file);if(token!==H.token)return;if(!Array.isArray(w.t)||!Array.isArray(w.x)||w.t.length!==t.waveform.sampleCount||w.x.length!==w.t.length||w.t.some(x=>typeof x!=='number'||!Number.isFinite(x))||w.x.some(x=>typeof x!=='number'||!Number.isFinite(x))||t.peaks.some(i=>i>=w.t.length))throw Error('Historical waveform or saved sample index is invalid.');H.wave=w;H.start=Math.min(...w.t);q('#history-wave-message').textContent=`${w.t.length.toLocaleString()} native samples · ${t.peaks.length} saved peaks · read only`;}
 plot();}
function renderRecords(rows){if(!Array.isArray(rows)||rows.length>100000)throw Error('Invalid historical annotation rows.');const host=q('#history-records'),table=document.createElement('table'),fields=[...new Set(rows.flatMap(r=>Object.keys(r)))],thead=document.createElement('thead'),tr=document.createElement('tr');for(const field of fields){const th=document.createElement('th');th.textContent=field;tr.append(th);}thead.append(tr);table.append(thead);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(const field of fields){const td=document.createElement('td');td.textContent=String(row[field]??'');td.title=td.textContent;tr.append(td);}body.append(tr);}table.append(body);host.replaceChildren(table);}
// Canvas coordinates are native times; gaps and reversals are drawn as breaks.
function plot(){const canvas=q('#history-wave'),rect=canvas.getBoundingClientRect(),width=Math.max(300,rect.width),height=330,dpr=devicePixelRatio||1;canvas.width=width*dpr;canvas.height=height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);if(!H.wave){ctx.fillStyle='#52665d';ctx.fillText('No bound waveform available; original annotation records remain visible.',18,35);return;}const w=H.wave,totalStart=Math.min(...w.t),end=Math.max(...w.t),span=q('#history-span').value,seconds=span==='full'?end-totalStart:Number(span);if(span==='full')H.start=totalStart;const a=H.start,z=Math.min(end,a+seconds),indices=[];for(let i=0;i<w.t.length;i++)if(w.t[i]>=a&&w.t[i]<=z)indices.push(i);q('#history-position').textContent=`${a.toFixed(2)}–${z.toFixed(2)} seconds`;q('#history-prev').disabled=span==='full'||a<=totalStart;q('#history-next').disabled=span==='full'||z>=end;if(!indices.length)return;let lo=Infinity,hi=-Infinity;for(const i of indices){lo=Math.min(lo,w.x[i]);hi=Math.max(hi,w.x[i]);}const range=Math.max(1,hi-lo);lo-=range*.12;hi+=range*.12;const X=t=>48+(t-a)/Math.max(.001,z-a)*(width-64),Y=x=>height-32-(x-lo)/(hi-lo)*(height-58);ctx.strokeStyle='#e6ece8';ctx.fillStyle='#75877e';ctx.font='11px system-ui';for(let k=0;k<=5;k++){const x=48+k/5*(width-64);ctx.beginPath();ctx.moveTo(x,16);ctx.lineTo(x,height-32);ctx.stroke();ctx.fillText((a+(z-a)*k/5).toFixed(1),x-10,height-12);}for(const [l,r]of H.selected.unreadable){if(r<a||l>z)continue;ctx.fillStyle='rgba(220,160,50,.18)';ctx.fillRect(X(Math.max(a,l)),16,X(Math.min(z,r))-X(Math.max(a,l)),height-48);}ctx.strokeStyle='#2d5151';ctx.lineWidth=1.25;ctx.beginPath();let prev=-2;for(const i of indices){if(i!==prev+1||w.t[i]<=w.t[prev]||w.t[i]-w.t[prev]>.25)ctx.moveTo(X(w.t[i]),Y(w.x[i]));else ctx.lineTo(X(w.t[i]),Y(w.x[i]));prev=i;}ctx.stroke();ctx.fillStyle='#ce625c';for(const i of H.selected.peaks){if(w.t[i]<a||w.t[i]>z)continue;ctx.beginPath();ctx.arc(X(w.t[i]),Y(w.x[i]),3.6,0,2*Math.PI);ctx.fill();}ctx.fillStyle='#52665d';ctx.fillText('ECG µV',6,14);ctx.fillText(hi.toFixed(0),2,31);ctx.fillText(lo.toFixed(0),2,height-33);}
async function open(files){const manifestFiles=files.filter(f=>f.name==='history_manifest.json');if(manifestFiles.length!==1)throw Error('Expected exactly one history manifest.');const f=manifestFiles[0],manifest=await jsonFile(f,25*1024*1024);validate(manifest);H.manifest=manifest;H.files=new Map(files.map(f=>[f._relative,f]));H.prefix=f._relative.slice(0,-f.name.length);for(const t of manifest.items)if(!H.files.has(H.prefix+t.recordsFile)||t.waveform&&!H.files.has(H.prefix+t.waveform.file))throw Error('History package is missing referenced records or waveforms.');q('#home').hidden=true;q('#workspace').hidden=true;q('#principles').hidden=true;q('#history-workspace').hidden=false;q('#history-title').textContent=manifest.title;q('#history-summary').textContent=`${manifest.items.length} historical tasks · ${manifest.items.filter(t=>t.waveform).length} bound waveforms`;q('#history-duration').replaceChildren(new Option('All durations',''));for(const duration of [...new Set(manifest.items.map(t=>t.durationGroup))].sort((a,b)=>parseFloat(a)-parseFloat(b)))q('#history-duration').append(new Option(duration,duration));q('#history-sampling').value='';q('#history-kind').value='';q('#history-search').value='';list();await select(manifest.items[0]);}
function boot(){for(const id of ['#history-duration','#history-sampling','#history-kind'])q(id).onchange=list;q('#history-search').oninput=list;q('#history-home').onclick=()=>{H.token++;H.manifest=null;H.wave=null;H.records=null;H.files=null;q('#history-workspace').hidden=true;q('#home').hidden=false;q('#principles').hidden=false;};q('#history-prev').onclick=()=>{if(H.wave){H.start=Math.max(Math.min(...H.wave.t),H.start-Number(q('#history-span').value));plot();}};q('#history-next').onclick=()=>{if(H.wave){H.start=Math.min(Math.max(...H.wave.t),H.start+Number(q('#history-span').value));plot();}};q('#history-span').onchange=()=>plot();q('#history-download').onclick=()=>{if(!H.records)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(H.records,null,2)],{type:'application/json'}));a.href=url;a.download=H.selected.clipId+'_historical_records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};addEventListener('resize',()=>{if(H.manifest)plot();});}
root.ECGHistory={open,validate};if(typeof document!=='undefined')boot();
})(globalThis);
